{
  "query": "query Documents { documents(limit: 1, page: 1) { data { id name } } }",
  "variables": {},
  "operationName": "Documents"
}

{
  "query": "mutation UpdateDocument($id: UUID!, $document: UpdateDocumentInput!) { updateDocument(id: $id, document: $document) { id name } }",
  "variables": { "id": "{{document_id}}", "document": { "name": "Updated OAuth example document" } },
  "operationName": "UpdateDocument"
}
